"""Lockfile incidents: parsing, incident generation, the uv runner and an end-to-end diagnosis."""

from __future__ import annotations

import json
import os
import stat
import sys
from pathlib import Path

import pytest

from regressleuth import Incident, investigate
from regressleuth.cli import main
from regressleuth.errors import InvalidIncident
from regressleuth.lockfiles import diff_pins, parse_requirements, read_lockfile, write_incident
from regressleuth.spec import validate

REQUIREMENTS = """\
# generated by uv pip compile
alpha==1.0 \\
    --hash=sha256:aaaa
Beta_Lib==2.1  # via alpha
colorama==0.4.6 ; sys_platform == "win32"
tomli==2.0.1 ; python_version < "3.11"
--index-url https://pypi.org/simple
"""

UV_LOCK = """\
version = 1
requires-python = ">=3.10"

[[package]]
name = "alpha"
version = "1.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "myproject"
version = "0.1.0"
source = { editable = "." }
dependencies = [{ name = "alpha" }]
"""

POETRY_LOCK = """\
[[package]]
name = "alpha"
version = "1.0"
description = ""
optional = false
python-versions = "*"

[metadata]
lock-version = "2.0"
content-hash = "abc"
"""


def test_requirements_pins_hashes_comments_and_markers() -> None:
    assert parse_requirements(REQUIREMENTS, "3.11") == {"alpha": "1.0", "beta-lib": "2.1"}
    assert parse_requirements(REQUIREMENTS, "3.10")["tomli"] == "2.0.1"
    assert parse_requirements("-e .\nalpha==1.0\n", "3.11") == {"alpha": "1.0"}  # the project itself
    for bad in ("-e ../other", "alpha>=1", "alpha @ https://example.com/a.whl"):
        with pytest.raises(InvalidIncident):
            parse_requirements(bad, "3.11")


def test_requirements_reject_unparsed_text_and_conflicting_active_pins() -> None:
    for bad in (
        "alpha==1.0 junk",
        "alpha==1.0 --hash=sha256:aaaa junk",
        "alpha==1.0\nalpha==2.0\n",
        'alpha==1.0 ; python_version >= "3.11"\nalpha==2.0\n',
        "alpha==1.0 ; invalid marker",
    ):
        with pytest.raises(InvalidIncident):
            parse_requirements(bad, "3.11")
    assert parse_requirements("alpha==1.0\nalpha==1.0\n", "3.11") == {"alpha": "1.0"}
    assert parse_requirements(
        'alpha==1.0 ; python_version < "3.11"\nalpha==2.0 ; python_version >= "3.11"\n',
        "3.11",
    ) == {"alpha": "2.0"}


def test_toml_lockfiles(tmp_path: Path) -> None:
    (tmp_path / "uv.lock").write_text(UV_LOCK, encoding="utf-8")
    (tmp_path / "poetry.lock").write_text(POETRY_LOCK, encoding="utf-8")
    assert read_lockfile(tmp_path / "uv.lock", "3.11") == {"alpha": "1.0"}  # the project itself is skipped
    assert read_lockfile(tmp_path / "poetry.lock", "3.11") == {"alpha": "1.0"}


def test_diff_marks_additions_and_removals() -> None:
    assert diff_pins({"a": "1", "b": "1", "c": "1"}, {"a": "2", "b": "1", "d": "3"}) == {
        "a": ("1", "2"),
        "c": ("1", "absent"),
        "d": ("absent", "3"),
    }


def lockfiles(tmp_path: Path, bad: str) -> tuple[Path, Path]:
    good_lock, bad_lock = tmp_path / "good.txt", tmp_path / "bad.txt"
    good_lock.write_text("alpha==1.0\nbeta==1.0\nshared==5.0\n", encoding="utf-8")
    bad_lock.write_text(bad, encoding="utf-8")
    return good_lock, bad_lock


def test_incident_is_valid_and_overwrites_only_with_force(tmp_path: Path) -> None:
    good_lock, bad_lock = lockfiles(tmp_path, "alpha==2.0\nbeta==2.0\nshared==5.0\ngamma==1.0\n")
    out = tmp_path / "incident"
    built = write_incident(
        good_lock, bad_lock, project=tmp_path, tests=["tests/test_x.py::test_x"], directory=out
    )
    assert built["changed"] == {"alpha": ("1.0", "2.0"), "beta": ("1.0", "2.0"), "gamma": ("absent", "1.0")}
    import yaml

    assert validate(yaml.safe_load((out / "incident.yaml").read_text(encoding="utf-8"))) == []
    cases = json.loads((out / "cases.json").read_text(encoding="utf-8"))
    assert cases["shared_pins"] == ["shared==5.0"] and cases["tests"] == ["tests/test_x.py::test_x"]
    with pytest.raises(InvalidIncident, match="already exist"):
        write_incident(good_lock, bad_lock, project=tmp_path, tests=["t"], directory=out)
    with pytest.raises(InvalidIncident, match="identical"):
        write_incident(good_lock, good_lock, project=tmp_path, tests=["t"], directory=tmp_path / "same")
    many = tmp_path / "many.txt"
    many.write_text("\n".join(f"p{i}==1" for i in range(13)) + "\n", encoding="utf-8")
    with pytest.raises(InvalidIncident, match="at most 12"):
        write_incident(good_lock, many, project=tmp_path, tests=["t"], directory=tmp_path / "m")


FAKE_UV = r"""
import os, sys
from pathlib import Path
args = sys.argv[1:]
PY = os.environ["FAKE_PYTHON"]
if args[0] == "venv":
    venv = Path(args[-1]); (venv / "bin").mkdir(parents=True)
    python = venv / "bin" / "python"
    python.write_text(f'#!/bin/sh\nFAKE_VENV="{venv}" exec "{PY}" "$@"\n')  # no nested quotes: Python 3.10+
    python.chmod(0o755)
elif args[:2] == ["pip", "install"] and "-r" in args:
    pins = Path(args[args.index("-r") + 1]).read_text().split()
    if "gamma==1.0" in pins and "alpha==1.0" in pins:
        sys.exit("gamma 1.0 requires alpha>=2")  # an uninstallable mix
"""

PROJECT_TEST = """\
import os
from pathlib import Path


def test_x():
    pins = Path(os.environ["FAKE_VENV"], "pins.txt").read_text().split()
    assert not ("alpha==2.0" in pins and "beta==2.0" in pins), "the upgrade pair breaks this test"
"""


def fake_uv(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    tools = tmp_path / "tools"
    tools.mkdir()
    (tools / "uv_impl.py").write_text(
        FAKE_UV.replace('os.environ["FAKE_PYTHON"]', repr(sys.executable)), encoding="utf-8"
    )
    uv = tools / "uv"
    uv.write_text(f'#!/bin/sh\nexec "{sys.executable}" "{tools / "uv_impl.py"}" "$@"\n', encoding="utf-8")
    uv.chmod(uv.stat().st_mode | stat.S_IEXEC)
    monkeypatch.setenv("PATH", f"{tools}:{os.environ['PATH']}")


def project_with_test(tmp_path: Path) -> Path:
    project = tmp_path / "project"
    (project / "tests").mkdir(parents=True)
    (project / "tests" / "test_x.py").write_text(PROJECT_TEST, encoding="utf-8")
    return project


def build(tmp_path: Path, project: Path, bad: str) -> Path:
    good_lock, bad_lock = lockfiles(tmp_path, bad)
    out = tmp_path / "incident"
    code = main(
        [
            "init",
            str(out),
            "--from-lockfiles",
            str(good_lock),
            str(bad_lock),
            "--project",
            str(project),
            "--test",
            "tests/test_x.py::test_x",
            "--no-install-project",
            "--python",
            "3",
        ]
    )
    assert code == 0
    return out


def test_end_to_end_diagnosis_from_lockfiles(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    fake_uv(tmp_path, monkeypatch)
    out = build(tmp_path, project_with_test(tmp_path), "alpha==2.0\nbeta==2.0\nshared==5.0\ndelta==3.0\n")
    report = investigate(Incident.from_file(out / "incident.yaml"), budget=8)
    assert report.status == "verified"
    assert report.diagnosis == ("alpha", "beta")
    assert {e.changed: e.outcome for e in report.experiments}[("alpha", "beta")] == "fail"
    assert (out / ".regressleuth-envs").is_dir()


def test_uninstallable_mix_is_incompatible(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from regressleuth.lockfile_runner import main as runner

    fake_uv(tmp_path, monkeypatch)
    out = build(tmp_path, project_with_test(tmp_path), "alpha==2.0\nbeta==2.0\nshared==5.0\ngamma==1.0\n")
    state = tmp_path / "state.json"
    result = tmp_path / "result.json"
    for components, expected in (
        ({"alpha": "1.0", "beta": "1.0", "gamma": "1.0"}, {"status": "incompatible"}),
        ({"alpha": "2.0", "beta": "2.0", "gamma": "1.0"}, {"metric": 0.0}),
        ({"alpha": "2.0", "beta": "1.0", "gamma": "1.0"}, {"metric": 1.0}),
    ):
        state.write_text(
            json.dumps({"components": components, "cases": str(out / "cases.json")}), encoding="utf-8"
        )
        assert runner(["--state", str(state), "--result", str(result)]) == 0
        assert json.loads(result.read_text(encoding="utf-8")) == expected


def test_groups_merge_an_upgrade_with_the_dependencies_it_dropped(tmp_path: Path) -> None:
    from regressleuth.lockfiles import expand, group_components

    changed = {"pandas": ("2.3.3", "3.0.0"), "pytz": ("2025.2", "absent"), "numpy": ("2.4.1", "2.4.2")}
    merged = group_components(changed, [["pandas", "pytz"]])
    assert merged == {
        "numpy": ("2.4.1", "2.4.2"),
        "pandas": ("pins:pandas==2.3.3,pytz==2025.2", "pins:pandas==3.0.0"),
    }
    assert expand("pandas", merged["pandas"][0]) == ["pandas==2.3.3", "pytz==2025.2"]
    assert expand("pytz", "absent") == [] and expand("numpy", "2.4.2") == ["numpy==2.4.2"]
    with pytest.raises(InvalidIncident, match="two or more changed"):
        group_components(changed, [["pandas", "unchanged"]])


def test_project_path_is_relative_to_the_incident(tmp_path: Path) -> None:
    good_lock, bad_lock = lockfiles(tmp_path, "alpha==2.0\nbeta==1.0\nshared==5.0\n")
    out = tmp_path / "incidents" / "one"
    write_incident(good_lock, bad_lock, project=tmp_path / "project", tests=["t"], directory=out)
    cases = json.loads((out / "cases.json").read_text(encoding="utf-8"))
    assert cases["project"] == "../../project"


