@pytest.mark.skipif(sys.platform == "win32", reason="the samples assume a non-Windows host")
def test_uv_lock_follows_markers_extras_and_groups(tmp_path: Path) -> None:
    lock = tmp_path / "uv.lock"
    lock.write_text(FORKED_UV_LOCK, encoding="utf-8")
    expected = {"uvicorn": "0.40.0", "httptools": "0.7.1", "matplotlib": "3.11.1", "pytest": "9.0.2"}
    assert read_lockfile(lock, "3.11") == {"numpy": "2.4.6", **expected}
    assert read_lockfile(lock, "3.12") == {"numpy": "2.5.3", **expected}


@pytest.mark.skipif(sys.platform == "win32", reason="the samples assume a non-Windows host")
def test_poetry_lock_filters_markers_python_and_extras(tmp_path: Path) -> None:
    lock = tmp_path / "poetry.lock"
    lock.write_text(MARKED_POETRY_LOCK, encoding="utf-8")
    # colorama is Windows-only in main but unconditional in the docs group
    assert read_lockfile(lock, "3.11") == {"numpy": "2.4.6", "tqdm": "4.70.1", "colorama": "0.4.6"}
    assert read_lockfile(lock, "3.12") == {"numpy": "2.5.3", "tqdm": "4.70.1", "colorama": "0.4.6"}


def test_custom_indexes_are_found_and_passed_to_uv(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from regressleuth.lockfiles import read_indexes

    (tmp_path / "uv.lock").write_text(
        FORKED_UV_LOCK.replace(
            'name = "pytest"\nversion = "9.0.2"\nsource = { registry = "https://pypi.org/simple" }',
            'name = "pytest"\nversion = "9.0.2"\nsource = { registry = "https://download.pytorch.org/whl/cpu" }',
        ),
        encoding="utf-8",
    )
    assert read_indexes(tmp_path / "uv.lock") == ["https://download.pytorch.org/whl/cpu"]
    requirements = tmp_path / "req.txt"
    requirements.write_text("--extra-index-url https://example.org/simple\nalpha==1\n", encoding="utf-8")
    assert read_indexes(requirements) == ["https://example.org/simple"]

    fake_uv(tmp_path, monkeypatch)
    calls = tmp_path / "calls.txt"
    impl = tmp_path / "tools" / "uv_impl.py"
    impl.write_text(
        f"import sys\nopen({str(calls)!r}, 'a').write(' '.join(sys.argv[1:]) + '\\n')\n"
        + impl.read_text(encoding="utf-8"),
        encoding="utf-8",
    )
    out = build(tmp_path, project_with_test(tmp_path), "alpha==2.0\nbeta==1.0\nshared==5.0\n")
    cases = json.loads((out / "cases.json").read_text(encoding="utf-8"))
    cases["index_urls"] = ["https://download.pytorch.org/whl/cpu"]
    (out / "cases.json").write_text(json.dumps(cases), encoding="utf-8")
    from regressleuth.lockfile_runner import main as runner

    state = tmp_path / "state.json"
    state.write_text(
        json.dumps({"components": {"alpha": "2.0"}, "cases": str(out / "cases.json")}), encoding="utf-8"
    )
    assert runner(["--state", str(state), "--result", str(tmp_path / "result.json")]) == 0
    install = next(
        line for line in calls.read_text(encoding="utf-8").splitlines() if line.startswith("pip install")
    )
    assert "--extra-index-url https://download.pytorch.org/whl/cpu" in install
